from moler.cmd.unix.exit import Exit


class Quit(Exit):
    """Quit command class."""

    def __init__(self, connection, prompt=None, expected_prompt=r'^moler_bash#', newline_chars=None, runner=None,
                 target_newline="\n"):
        """
        Quit command.

        :param connection: connection to device.
        :param expected_prompt: prompt on device changed by this command.
        :param prompt: expected prompt sending by device after command execution. Maybe String or compiled re.
        :param newline_chars:  new line chars on device (a list).
        :param runner: runner to run command.
        :param target_newline: newline on device when command is finished and prompt is changed.
        """
        super(Quit, self).__init__(connection=connection, prompt=prompt, expected_prompt=expected_prompt,
                                   newline_chars=newline_chars, target_newline=target_newline, runner=runner)

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "quit"
        return cmd


COMMAND_OUTPUT = """>|quit
moler_bash# """

COMMAND_KWARGS = {
    "expected_prompt": r'^moler_bash#'
}

COMMAND_RESULT = {}
